Reset Your Password

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            line-height: 1.6;
            color: #333;
            margin: 0;
            padding: 0;
            background-color: #f9f9f9;
        }

        .container {
            max-width: 600px;
            margin: 20px auto;
            background: #ffffff;
            border-radius: 12px;
            overflow: hidden;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.05);
        }

        .header {
            background-color: #8B5AB1;
            padding: 40px 20px;
            text-align: center;
        }

        .header h1 {
            color: #ffffff;
            margin: 0;
            font-size: 28px;
            font-weight: 700;
            letter-spacing: -0.5px;
        }

        .content {
            padding: 40px 30px;
            text-align: center;
        }

        .content p {
            margin-bottom: 25px;
            font-size: 16px;
            color: #555;
        }

        .footer {
            background-color: #f4f4f4;
            padding: 20px;
            text-align: center;
            font-size: 12px;
            color: #888;
        }

        .button-container {
            margin: 35px 0;
        }

        .button {
            display: inline-block;
            padding: 16px 36px;
            background-color: #8B5AB1;
            color: #ffffff !important;
            text-decoration: none;
            border-radius: 30px;
            font-weight: 700;
            font-size: 16px;
            transition: all 0.3s ease;
            box-shadow: 0 4px 12px rgba(139, 90, 177, 0.3);
        }

        .button:hover {
            background-color: #7a4a9a;
            transform: translateY(-2px);
            box-shadow: 0 6px 15px rgba(139, 90, 177, 0.4);
        }

        .link-text {
            word-break: break-all;
            color: #8B5AB1;
            font-size: 13px;
            margin-top: 25px;
        }

